INSERT INTO content_unit (slug, bucket, title, kind, sort_order) VALUES ('ayyuhal-walad', 'Islamic', 'Ayyuha al-Walad', 'book', 0) ON CONFLICT(slug) DO UPDATE SET bucket = excluded.bucket, title = excluded.title;
INSERT INTO unit_detail (slug, author, author_short, title_arabic, title_language, study_track, blurb_html, edition_note, cover_key, pdf_key, published_at, source_commit) VALUES ('ayyuhal-walad', 'Imam al-Ghazali', 'Al-Ghazali', 'أيها الولد', 'ar', 'theology', '<p>This is a letter of spiritual counsel. A former student, having spent years mastering the religious sciences under his teacher, asked what, of all he had learned, would truly serve him in the grave and on the Day of Judgment. Everything that follows is the teacher''s written reply. The title, <em>Ayyuha al-Walad</em> — &quot;O son&quot; — is the affectionate way he addresses the young man throughout; it names a beloved disciple, not a child of his body.</p>', NULL, 'ayyuhal-walad/cover.png', 'ayyuhal-walad/book.pdf', '2026-09-01T23:51:03Z', '9dcd3c856fc68c1ebd2ae397f48bd2f04fc08e61');
